#!/bin/bash
set -e

# Speed pass 2:
# - Doctor Dashboard's 15s auto-refresh was making 3 sequential
#   round-trips instead of parallel -- now uses Promise.all.
# - Cash Management had real redundant work: getCloseDayReadiness()
#   internally called getReconciliationData(), which itself called
#   getTodayCollectionSummary() -- and the page's refresh() was ALSO
#   calling both of those separately. Same underlying query was
#   running up to 4x per page load. Now runs once, reused, and
#   everything else in refresh() runs in parallel.
# - Added missing index on queue_entries.issued_at (used by every
#   getQueues() poll -- 15s interval across 3+ dashboards).
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/doctor-dashboard"
echo "" | base64 -d > "app/(main)/doctor-dashboard/page.js"
echo "Wrote app/(main)/doctor-dashboard/page.js"

mkdir -p "app/(main)/cash-management"
echo "" | base64 -d > "app/(main)/cash-management/actions.js"
echo "Wrote app/(main)/cash-management/actions.js"

mkdir -p "app/(main)/cash-management"
echo "" | base64 -d > "app/(main)/cash-management/page.js"
echo "Wrote app/(main)/cash-management/page.js"

git add "app/(main)/doctor-dashboard/page.js" "app/(main)/cash-management/actions.js" "app/(main)/cash-management/page.js"
git commit -m "Speed: parallelize dashboard refreshes, eliminate redundant Cash Management queries, add queue index"
git push

echo "Done."
